      "Notes, Conseils, Astuces :",
      "Le grué est la fève de cacao torréfiée, concassée ; il apporte dans cette nougatine un arôme de chocolat incomparable de pureté. Les abricots moelleux sont des abricots déshydratés, ni secs, ni confits, mais juste hydratés à souhait pour préserver leur moelleux. On peut les remplacer par des abricots secs que l’on réhydrate avec de l’eau et du jus de citron mais ceux-ci laissent un arrière-goût que je trouve désagréable. La tarte doit être à température ambiante 22/24°C au moment de la servir.",
